(7510, 330, 'rules_security_and_property_0_text', '<h4>Husregler</h4>\r\n<ul>\r\n    <li>– Innsjekking er 14:00 til 18:00</li>\r\n    <li>– Utsjekking før kl. 12:00</li>\r\n    <li>– Maksimalt 8 gjester</li>\r\n</ul>'),
(7511, 330, '_rules_security_and_property_0_text', 'field_64e5e3315d40d'),
(7512, 330, 'rules_security_and_property_1_text', '<h4>Sikkerhet og eiendom</h4> \r\n<ul>\r\n    <li>– Sikkerhetskamera/opptaksenhet</li>\r\n    <li>– Karbonmonoksidvarsler</li> \r\n    <li>– Røykvarsler</li>\r\n</ul>'),
