(7893, 411, '_form', '<div class=\"row\">\n\n	<div class=\"col-sm-8\">\n            <div class=\"any_que_form_left\">\n		<div class=\"row\">\n                        <h3>Your Personal Details</h3>\n			<div class=\"col-sm-6\">[text firstname placeholder \"First name\"]</div>\n\n			<div class=\"col-sm-6\">[text lastName placeholder \"Last Name\"]</div>\n\n			<div class=\"col-sm-12\">[email* email placeholder \"Email\"]</div>\n\n			<div class=\"col-sm-12\">[tel phone placeholder \"Phone\"]</div>\n\n			<div class=\"col-sm-12\">[date date placeholder \"DD/MM/YYYY\"]</div>\n\n			<div class=\"col-sm-12\">[textarea message placeholder \"Message\"]</div>\n		</div>\n	    </div>\n        </div>\n	<div class=\"col-sm-4\">\n           <div class=\"any_que_form_right\">\n                <h3>Share your home</h3>\n		[select choosecity \"Choose City\" \"City 1\" \"City 2\" \"City 3\"]\n\n		[select choosearea \"Choose Area\" \"Area 1\" \"Area 2\" \"Area 3\"]\n\n		[select chooserooms \"Choose Rooms\" \"Rooms 1\" \"Rooms 2\" \"Rooms 3\"]\n\n		[select chooseavailability \"Choose Availability\" \"Availability 1\" \"Availability 2\" \"Availability 3\"]\n            </div>  \n	</div>\n	[submit \"Send in your request here\"]\n	\n</div>'),
