INSERT INTO `vv_email_templates` (`email_id`, `code`, `locale`, `subject`, `body`) VALUES
(1, 'user_registration', 'en', 'Welcome to Visit Vietnam', '<p>Hello %FIRSTNAME%,</p>\r\n<p>Thank you for signing up on Visit Vietnam,</p>\r\n<p>Here\\\'s your login information:<br />Username: %USERNAME%<br />Password: %PASSWORD%</p>\r\n<p>Thanks,<br />Visit Vietnam Support</p>'),
(2, 'user_booking_confirmation', 'en', 'Confirmation for Booking ID #%BOOKING_NUM% Check-in %CHECK-IN_DATE%', '<h2 style=\\\"text-align: center;\\\">Your booking is now confirmed!</h2>\r\n<p>Hello %FIRSTNAME% %LASTNAME%,</p>\r\n<p>For reference, your booking ID is %BOOKING_NUM%. To view, cancel, or modify your booking, use our easy self service.</p>\r\n<p style=\\\"text-align: center;\\\"><a href=\\\"%BOOKING_LINK% \\\"><button style=\\\"border: 0px none; background-color: #024041; color: #ffffff; border-radius: 4px; padding: 10px 20px;\\\" type=\\\"button\\\">MANAGE BOOKING</button></a></p>\r\n<p>&nbsp;</p>\r\n<h3 style=\\\"margin-bottom: 0; line-height: 1.1;\\\">%APARTMENT_NAME%</h3>\r\n<p style=\\\"margin-top: 0;\\\">%DISTRICT_NAME%</p>\r\n<p>CHECK-IN : %CHECK-IN_DATE%<br />CHECK-OUT: %CHECK-OUT_DATE%</p>\r\n<p>%BOOKING_TABLE%</p>\r\n<p>Thanks,<br />Visit Vietnam Support</p>   '),
(3, 'admin_booking_confirmation', 'en', 'Visit Vietnam New Booking #%BOOKING_NUMBER%', '<h3 style=\\\"margin-bottom: 0; line-height: 1.1;\\\">%APARTMENT_NAME%</h3>\r\n<p style=\\\"margin-top: 0;\\\">%CITY_NAME%</p>\r\n<p>CHECK-IN : %CHECK-IN_DATE%<br />CHECK-OUT: %CHECK-OUT_DATE%<br />NAME: %FIRSTNAME% %LASTNAME%<br />EMAIL: %EMAIL%<br />ROOMS: %ROOMS%<br />ADULTS: %ADULTS%<br />CHILDREN: %CHILDREN%</p>\r\n<p>%BOOKING_TABLE%<br />%BOOKING_TOTALS%</p>\r\n<p>&nbsp;</p>'),
(4, 'user_new_task_notification', 'en', 'Visit Vietnam: A new task has been assigned to you', '<p style=\\\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\\\">Hello DanTen Test,</p><p style=\\\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\\\"><br></p><p style=\\\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\\\">A, new Task has been assigned to you titled&nbsp;<span style=\\\"font-weight: bolder;\\\">\\\"%TASK_TITLE%\\\"</span>,</p><p style=\\\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\\\"><br>click on the link below to check<br><ahref=\\\"%task_link%\\\">%TASK_LINK%</ahref=\\\"%task_link%\\\"></p>'),
(5, 'user_task_updated_notification', 'en', 'Visit Vietnam: Your task has been updated', '<p style=\\\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\\\">Hello %FIRSTNAME%,</p><p style=\\\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\\\"><br></p><p style=\\\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\\\">Your task&nbsp;<span style=\\\"font-weight: bolder;\\\">\\\"%TASK_TITLE%\\\"</span>,&nbsp; has been updated</p><p style=\\\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\\\"><br></p><p style=\\\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\\\">Title: %TASK_TITLE%</p><p style=\\\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\\\">description:%TASK_DESCRIPTION%</p><p style=\\\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\\\"><br>click on the link below to check<br><ahref=\\\"%task_link%\\\">%TASK_LINK%</ahref=\\\"%task_link%\\\"></p>'),
(6, 'user_new_task_comment_notification', 'en', 'Visit Vietnam: A new comment has been posted to your task', '<p style=\\\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\\\">Hello DanTen Test,</p><p style=\\\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\\\"><br></p><p style=\\\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\\\">A, new comment has been posted to the Task that has been assigned to you titled&nbsp;<span style=\\\"font-weight: bolder;\\\">\\\"%TASK_TITLE%\\\"</span>,</p><p style=\\\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\\\"><br></p><p style=\\\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\\\">AUTHOR: %COMMENT_AUTHOR%</p><p style=\\\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\\\">COMMENT:</p><p style=\\\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\\\">%COMMENT%</p><p style=\\\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\\\"><br>click on the link below to check<br><ahref=\\\"%task_link%\\\">%TASK_LINK%</ahref=\\\"%task_link%\\\"></p>'),
(7, 'host_application_submitted', 'en', 'Thank you for your Vietstays host application', '<p>Hi %FULL_NAME%,</p><p><br></p><p>Thank you for your application to become a Vietstays host. We have received it and will be in touch soon.</p><p><strong><br></strong></p><p><strong>Application ID:</strong> %APPLICATION_REF%</p><p><br></p><p>Our team normally reviews applications within 2–3 business days.</p><p><br></p><p>If you have questions, contact us at <a href=\"mailto:%CONTACT_EMAIL%\">%CONTACT_EMAIL%</a> and include your application ID.</p>'),
(8, 'host_application_under_review', 'en', 'Your Vietstays host application is under review', '<p>Hi %FULL_NAME%,</p><p><br></p><p>Our team is now reviewing your host application. This normally takes 2–3 business days.</p><p><strong><br></strong></p><p><strong>Application ID:</strong> %APPLICATION_REF%</p>'),
(9, 'host_application_approved', 'en', 'Your Vietstays host application has been approved', '<p>Hi %FULL_NAME%,</p><p><br></p><p>Great news — your application to become a Vietstays host has been approved.</p><p><br></p><p>Please verify your email address and set your password to activate your host account:</p><p><br></p><p><a href=\"%ACTIVATION_LINK%\">Activate my host account</a></p><p><br></p><p>This link is valid for 7 days.</p><p><strong>Application ID:</strong> %APPLICATION_REF%</p>'),
(10, 'host_application_rejected', 'en', 'Update on your Vietstays host application', '<p>Hi %FULL_NAME%,</p><p><br></p><p>Thank you for your interest in Vietstays. After review, we are unable to approve your application at this time.</p><p><br></p><p>%REJECTION_REASON_BLOCK%%REJECTION_COMMENT_BLOCK%</p><p><br></p><p>If you believe this decision was made in error, you may appeal by emailing <a href=\"mailto:%CONTACT_EMAIL%\">%CONTACT_EMAIL%</a> and including your application ID <strong>%APPLICATION_REF%</strong>.</p>'),
(11, 'host_welcome', 'en', 'Welcome to the Vietstays host team', '<p>Hi %FULL_NAME%,</p><p><br></p><p>Welcome to Vietstays! Your email is verified and your host backend account is now active.</p><p><br></p><p>You can sign in to manage apartments, bookings, and your operations team here:</p><p><br></p><p><a href=\"%HOST_PORTAL_LINK%\">%HOST_PORTAL_LINK%</a></p><p><br></p><p>We recommend bookmarking the portal and completing your apartment setup as your first step.</p><p><br></p><p>Thanks,</p><p>VietStays</p>'),
(12, 'host_activation_reminder', 'en', 'Reminder: activate your Vietstays host account', '<p>Hi %FULL_NAME%,</p><p><br></p><p>This is a friendly reminder to verify your email and set your password so you can access the Vietstays host portal.</p><p><br></p><p><a href=\"%ACTIVATION_LINK%\">Activate my host account</a></p>');
